function diffLines(a, bLines) {
  const added = []
  const removed = []
  const aSet = new Set(a)
  const bSet = new Set(bLines)

  for (const line of a) {
    if (!bSet.has(line)) removed.push(line)
  }
  for (const line of bLines) {
    if (!aSet.has(line)) added.push(line)
  }

  return { added, removed }
}
